import{_ as l,l as i,o as e,c as s,v as t,p as n,x as o,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"TCAM 查表","description":"","frontmatter":{"title":"TCAM 查表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tcam-lookup.md","filePath":"cs/tcam-lookup.md","lastUpdated":1789023840000}'),A={name:"cs/tcam-lookup.md"};function h(C,a,M,T,u,m){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="tcam-查表" tabindex="-1">TCAM 查表 <a class="header-anchor" href="#tcam-查表" aria-label="Permalink to &quot;TCAM 查表&quot;">​</a></h1><div class="epigraph"><p>三态内容寻址把前缀与掩码一次并行匹配，再按优先级编码出最长前缀；容量贵，所以 FIB 与 ACL 都在抢这块硅。</p><footer>—— 据 McAuley and Francis, Fast Routing Table Lookup, INFOCOM 1993；交换芯片查表实践整理</footer></div><p><a href="/cs/router-architecture">上一课</a> 假定 LPM 线速。主干<a href="/cs/lpm">最长前缀匹配</a> 给算法直觉。缺口是<strong>硬件怎么一次比完</strong>：TCAM 的 0/1/X、优先级编码器、与 SRAM 流水对照。本课不把 OpenFlow 流表写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>软件树/哈希在最坏深度上抖动。TCAM：每个比特存值与掩码，包键并行比较，命中集用优先级取最长或最先。ACL 五元组同样是三态。代价：功耗、容量（数十万量级则贵）、更新要插空洞避免打断线速。算法类 LPM（树、 trie）用 SRAM 换更新友好，最坏延迟要工程保证。</p><p>不要把 TCAM 写成「无限智能」：表满则无法再装更细前缀，运营要聚合。</p><p><span class="marginnote">TCAM 也用于 MAC、流表。本课不讲电路晶体管。更新与查表并发是芯片内部课题。</span></p><h3 id="并行匹配有容量税" tabindex="-1">并行匹配有容量税 <a class="header-anchor" href="#并行匹配有容量税" aria-label="Permalink to &quot;并行匹配有容量税&quot;">​</a></h3><p>三态一次比完，再取 LPM/优先级。表满无法再装细前缀。IPv6 更宽的键更吃硅。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：TCAM 并行 vs trie 多级。画：键 → 匹配向量 → 优先级 → 动作（下一跳、ACL drop）。RPKI 无效丢弃是动作之一，仍占表项。</p>',11)),(e(),n(d,null,{default:o(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E5%8C%85%E9%94%AE%22%5D%20--%3E%20TCAM%5B%22%E5%B9%B6%E8%A1%8C%E4%B8%89%E6%80%81%E5%8C%B9%E9%85%8D%22%5D%0A%20%20TCAM%20--%3E%20PRI%5B%22%E4%BC%98%E5%85%88%E7%BA%A7%2FLPM%22%5D%0A%20%20PRI%20--%3E%20ACT%5B%22%E4%B8%8B%E4%B8%80%E8%B7%B3%E6%88%96%20ACL%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>EVPN MAC 规模可压垮表，要聚合或层次。ECMP 下一跳组在 SRAM，TCAM 只指向组号。OpenFlow 后课把多级流表暴露给控制面，硬件仍常是 TCAM 级联。与容量 \\(C\\) 无关：查表是转发税，不是信道。</p><p>安全：故意装大量更长前缀可耗尽 TCAM，像 MAC 耗尽。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入算法 LPM 的全部压缩 trie。SDN 与 OpenFlow 是下一课。后课默认：线速 LPM/ACL 靠 TCAM 或等价并行匹配，容量是硬约束。</p><p>IPv6 更宽的键更吃 TCAM，这是过渡课留下的硬件账。</p><p>上一课留下的缺口在本课收口；「TCAM 查表」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/sdn-openflow">SDN 与 OpenFlow</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TCAM 并行匹配三态键，再取最优。</li><li>容量与功耗限制细前缀与 ACL。</li><li>SRAM 算法查表换更新，要保证最坏时延。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：McAuley–Francis, 1993；芯片实践。</li></ul>',10))])}const E=l(A,[["render",h]]);export{P as __pageData,E as default};
